"use client";

import { useEffect, useRef } from "react";

type Props = {
  reduced: boolean;
};

/**
 * The full-page CRT overlay — the crt-scanline technique. Two fixed layers:
 *
 *   1. A scanline grille: a 2px-tall repeating-linear-gradient of dark
 *      stripes, fixed over the whole viewport, pointer-events: none. It is
 *      the aperture grille of the tube.
 *   2. A subtle vignette + a JS-modulated flicker on the grille's opacity
 *      (0.16 → 0.22 over ~4.7s), so the screen breathes like a real CRT.
 *
 * The flicker rAF pauses when the tab is hidden. Under reduced motion the
 * grille is rendered statically (a real, composed layer — the page still
 * reads as a CRT, it just does not flicker). The overlay never carries
 * text, so contrast is unaffected; the grille sits *behind* text via
 * z-index and is dark enough at 18% that AA headings stay AA.
 *
 * The element itself is aria-hidden and decorative; the overlay is purely
 * atmospheric.
 */
export default function CRTOverlay({ reduced }: Props) {
  const grilleRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (reduced) return;
    const grille = grilleRef.current;
    if (!grille) return;

    let raf = 0;
    let running = false;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      if (now - last < 90) return; // ~11Hz: subtle, never seizure-risk
      last = now;
      // a slow sinusoidal breath around the grille's base opacity
      const t = now / 4700;
      const o = 0.16 + 0.06 * (0.5 + 0.5 * Math.sin(t * Math.PI * 2));
      grille.style.opacity = o.toFixed(3);
    };

    const sync = () => {
      const should = !document.hidden;
      if (should && !running) {
        running = true;
        last = performance.now();
        raf = requestAnimationFrame(step);
      } else if (!should && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const onVisibility = () => sync();
    document.addEventListener("visibilitychange", onVisibility);
    sync();

    return () => {
      running = false;
      cancelAnimationFrame(raf);
      document.removeEventListener("visibilitychange", onVisibility);
      grille.style.opacity = "";
    };
  }, [reduced]);

  return (
    <div className="pixel-crt" aria-hidden="true">
      <div className="pixel-crt__vignette" />
      <div ref={grilleRef} className="pixel-crt__scan" />
    </div>
  );
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

/** Ticker speed in px/second: resting drift, and what full rush adds. */
const BASE_PX_S = 44;
const RUSH_PX_S = 240;

/**
 * Chiptune credits + high-score table, one continuous line. Each entry is
 * a real fictional score with a real fictional player initial, written in
 * the arcade's bilingual voice — cheerful, competitive, a little boastful.
 */
const ROWS = [
  { rank: "1UP", score: "9999990", name: "PIX", ko: "최고기록" },
  { rank: "2UP", score: "0842300", name: "KYU", ko: "은메달" },
  { rank: "3UP", score: "0710042", name: "NEO", ko: "동메달" },
  { rank: "4UP", score: "0500128", name: "ARI", ko: "콤보 마스터" },
  { rank: "5UP", score: "0299001", name: "ZAI", ko: "숨은 주인공" },
  { rank: "6UP", score: "0128000", name: "MOO", ko: "계속 도전 중" },
] as const;

const CREDITS = [
  "PIXEL ARCADE STUDIO · EST. 2003 · SEOUL",
  "SOUND DRIVER — DUNGEON SOUND TEAM",
  "PIXEL ART — ARI & KYU",
  "DESIGN — NEO",
  "SPECIAL THANKS — EVERY QUARTER YOU SPENT",
] as const;

type Props = {
  reduced: boolean;
  /** Live scroll rush energy 0→1 from useScrollRush — read inside rAF. */
  energyRef: RefObject<number>;
};

/**
 * The high-score marquee: one JS-driven ticker whose speed is coupled to
 * scroll rush — read slowly and the credits drift by; scroll and the
 * scoreboard hurries after you. The moving track is aria-hidden and
 * duplicated once for a seamless wrap; screen readers get the scores and
 * credits exactly once from a visually-hidden list. Without JavaScript
 * (or with reduced motion) the strip is simply a static line.
 */
export default function HighScoreMarquee({ reduced, energyRef }: Props) {
  const clipRef = useRef<HTMLDivElement | null>(null);
  const trackRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (reduced) return;
    const clip = clipRef.current;
    const track = trackRef.current;
    if (!clip || !track) return;

    let raf = 0;
    let running = false;
    let visible = true;
    let x = 0;
    let runW = 0;
    let last = 0;

    const measure = () => {
      runW = track.scrollWidth / 2; // two identical runs
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 64);
      last = now;
      x -= (dt / 1000) * (BASE_PX_S + energyRef.current * RUSH_PX_S);
      if (runW > 0 && -x >= runW) x += runW;
      track.style.transform = `translate3d(${x.toFixed(2)}px, 0, 0)`;
    };

    const sync = () => {
      const should = visible && !document.hidden;
      if (should && !running) {
        running = true;
        last = performance.now();
        raf = requestAnimationFrame(step);
      } else if (!should && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const onVisibility = () => sync();

    const io = new IntersectionObserver((hits) => {
      visible = hits[hits.length - 1].isIntersecting;
      sync();
    });
    io.observe(clip);

    const ro = new ResizeObserver(measure);
    ro.observe(track);

    document.addEventListener("visibilitychange", onVisibility);
    measure();
    sync();

    return () => {
      running = false;
      cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      track.style.transform = "";
    };
  }, [reduced, energyRef]);

  return (
    <section className="pixel-marquee" aria-label="High scores and credits">
      <ul className="pixel-sr">
        {ROWS.map((r) => (
          <li key={r.rank}>
            {r.rank} {r.score} {r.name} —{" "}
            <span lang="ko">{r.ko}</span>
          </li>
        ))}
        {CREDITS.map((c) => (
          <li key={c}>{c}</li>
        ))}
      </ul>
      <div ref={clipRef} className="pixel-marquee__clip" aria-hidden="true">
        <div ref={trackRef} className="pixel-marquee__track">
          {[0, 1].map((copy) => (
            <div key={copy} className="pixel-marquee__run">
              {ROWS.map((r) => (
                <span key={r.rank} className="pixel-marquee__score">
                  <span className="pixel-marquee__rank">{r.rank}</span>
                  <span className="pixel-marquee__num">{r.score}</span>
                  <span className="pixel-marquee__name">{r.name}</span>
                  <span className="pixel-marquee__ko" lang="ko">
                    {r.ko}
                  </span>
                </span>
              ))}
              {CREDITS.map((c, i) => (
                <span key={i} className="pixel-marquee__credit">
                  <span className="pixel-marquee__star">★</span>
                  {c}
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useRef, type CSSProperties } from "react";
import PixelSprite from "./PixelSprite";
import {
  HERO_BLINK_EYES,
  HERO_BLINK_ERASE,
  HERO_FRAME_0,
} from "./sprites";
import { useSpriteCycle } from "../hooks/useSpriteCycle";

type Props = {
  /** Pixel pitch. Hero mascot renders at 3px for ~48px tall. */
  scale?: number;
  reduced: boolean;
  className?: string;
  style?: CSSProperties;
};

/**
 * The hero mascot: a cheerful 16×16 cabinet sprite that blinks on idle.
 * The cycle is two frames — eyes-open (frame 0) and a blink — driven by
 * `useSpriteCycle`, which pauses offscreen and under reduced motion.
 *
 * Because the blink is implemented as an *overlay* of a few pixels over
 * the base frame (erase the open eyes with body color, draw two short
 * closed-eye bars), pausing always leaves a complete, legible sprite on
 * screen. Reduced motion parks on frame 0 — a real, composed still.
 */
export default function PixelCharacter({
  scale = 3,
  reduced,
  className,
  style,
}: Props) {
  const ref = useRef<HTMLSpanElement | null>(null);
  const frame = useSpriteCycle(ref, 2, reduced);

  return (
    <span
      ref={ref}
      className={className ? `pixel-char ${className}` : "pixel-char"}
      style={style}
    >
      <PixelSprite
        pixels={HERO_FRAME_0}
        scale={scale}
        label="PIXEL — the studio mascot, a smiling bubblegum-pink arcade cabinet with a cyan screen-face, a mint cheek, and a yellow antenna lamp. 픽셀 — 스튜디오 마스코트, 미소 짓는 버블검 핑크 아케이드 캐비닛."
      />
      {frame === 1 && (
        <span className="pixel-char__blink" aria-hidden="true">
          <PixelSprite pixels={HERO_BLINK_ERASE} scale={scale} />
          <PixelSprite pixels={HERO_BLINK_EYES} scale={scale} />
        </span>
      )}
    </span>
  );
}

"use client";

import { type CSSProperties } from "react";
import { spriteSize, spriteToBoxShadow, type Pixel } from "./sprites";

type Props = {
  /** The sprite pixels to render. */
  pixels: readonly Pixel[];
  /** Pixel pitch multiplier — 1 = 1px pixels, 2 = 2px, etc. */
  scale?: number;
  /** Extra class for art direction (e.g. .pixel-hero__sprite). */
  className?: string;
  /** Inline style passthrough (positioning). */
  style?: CSSProperties;
  /** Accessible label — the sprite is decorative by default (aria-hidden). */
  label?: string;
};

/**
 * The one-element pixel renderer: a 1px×1px anchor whose `box-shadow` is the
 * whole sprite. Each lit pixel is one shadow tuple, so a 200-pixel mascot
 * is a single DOM node with a long shadow list — the browser composites it
 * once. `image-rendering: pixelated` is set in CSS so any scaling stays
 * crisp-blocky instead of bilinear-soft.
 *
 * Decorative sprites are aria-hidden; pass a `label` to expose the sprite
 * as a role="img" with a bilingual description (used on the hero mascot).
 */
export default function PixelSprite({
  pixels,
  scale = 1,
  className,
  style,
  label,
}: Props) {
  const { width, height } = spriteSize(pixels);
  const box = spriteToBoxShadow(pixels, scale);
  const anchorStyle: CSSProperties = {
    width: `${scale}px`,
    height: `${scale}px`,
    boxShadow: box,
  };
  const wrapStyle: CSSProperties = {
    width: `${width * scale}px`,
    height: `${height * scale}px`,
    ...style,
  };
  if (label) {
    return (
      <span
        className={className ? `pixel-sprite ${className}` : "pixel-sprite"}
        style={wrapStyle}
        role="img"
        aria-label={label}
      >
        <span className="pixel-sprite__anchor" style={anchorStyle} />
      </span>
    );
  }
  return (
    <span
      className={className ? `pixel-sprite ${className}` : "pixel-sprite"}
      style={wrapStyle}
      aria-hidden="true"
    >
      <span className="pixel-sprite__anchor" style={anchorStyle} />
    </span>
  );
}

/**
 * Pixel-art sprite data + a tiny renderer that turns a grid of (x, y, color)
 * tuples into a single CSS `box-shadow` value.
 *
 * Each sprite is one box-shadow per lit pixel: a 1px×1px anchor element
 * carries a shadow list of `${x}px ${y}px 0 ${color}` tuples. The browser
 * composites the whole sprite as one element, so a 200-pixel mascot is one
 * DOM node — this is the "ascii-render" technique: pixel density described
 * by a character grid, rendered by the shadow stack instead of an <img>.
 *
 * Coordinates are in pixel units from the sprite's top-left. Colors are
 * looked up in SPRITE_PALETTE so the data stays compact and the palette
 * stays declared in one place (every rendered color is a named token).
 *
 * The two hero mascot frames share every pixel except the eyes — frame 0
 * is open, frame 1 is a blink — so the idle cycle is a real two-frame
 * animation, not a re-render. Reduced motion parks on frame 0.
 */

export const SPRITE_PALETTE = {
  k: "#0a0a12", // outline / ground — the CRT mask around the sprite
  p: "#ff3d8a", // bubblegum body
  pl: "#ff8fb8", // bubblegum highlight
  pd: "#c8265f", // bubblegum shadow
  c: "#00e5ff", // cyan screen
  cl: "#7df4ff", // cyan screen highlight
  w: "#ffffff", // eye white / sparkle
  y: "#fff44f", // acid lamp
  m: "#4dff9f", // mint cheek
  s: "#c8d0d8", // chrome buckle
} as const;

export type Pixel = readonly [number, number, keyof typeof SPRITE_PALETTE];

/** Hero mascot — frame 0 (eyes open). A cheerful 16×16 cabinet sprite. */
export const HERO_FRAME_0: readonly Pixel[] = [
  // outline crown
  [0, 1, "k"], [1, 0, "k"], [2, 0, "k"], [3, 1, "k"],
  [12, 1, "k"], [13, 0, "k"], [14, 0, "k"], [15, 1, "k"],
  // top row body
  [1, 1, "p"], [2, 1, "p"], [3, 2, "p"], [12, 2, "p"], [13, 1, "p"], [14, 1, "p"],
  [2, 2, "pl"], [13, 2, "pl"],
  // body block rows 2-12
  ...row(2, 13, 2, "p"),
  ...row(1, 14, 3, "p"),
  ...row(0, 15, 4, "p"),
  ...row(0, 15, 5, "p"),
  ...row(0, 15, 6, "p"),
  ...row(0, 15, 7, "p"),
  ...row(0, 15, 8, "p"),
  ...row(0, 15, 9, "p"),
  ...row(0, 15, 10, "p"),
  ...row(1, 14, 11, "p"),
  ...row(2, 13, 12, "p"),
  // screen bezel (cyan inset)
  ...border(3, 4, 12, 8, "c"),
  // screen face fill highlight top-left
  [4, 5, "cl"], [5, 5, "cl"], [4, 6, "cl"],
  // eyes OPEN
  [5, 6, "k"], [6, 6, "k"],
  [9, 6, "k"], [10, 6, "k"],
  // mouth smile
  [5, 7, "k"], [6, 7, "k"], [7, 7, "k"], [8, 7, "k"], [9, 7, "k"], [10, 7, "k"],
  // cheeks (mint)
  [3, 7, "m"], [12, 7, "m"],
  // bottom shadow line
  ...row(2, 13, 13, "pd"),
  // feet
  [3, 13, "k"], [4, 14, "k"], [5, 14, "k"],
  [10, 14, "k"], [11, 14, "k"], [12, 13, "k"],
  // antenna lamp
  [7, 0, "y"], [8, 0, "y"],
] as const;

/**
 * Hero mascot — blink overlay. Frame 1 is frame 0 with the open eyes
 * removed and two short closed-eye bars drawn one row lower. Rather than
 * ship a second full grid, the component renders frame 0 and overlays
 * these few pixels (in the body color, to erase the open eyes) plus the
 * closed-eye bars. The blink is a real second frame; the data stays small.
 */
export const HERO_BLINK_ERASE: readonly Pixel[] = [
  [5, 6, "c"], [6, 6, "c"],
  [9, 6, "c"], [10, 6, "c"],
] as const;

export const HERO_BLINK_EYES: readonly Pixel[] = [
  [5, 7, "k"], [6, 7, "k"],
  [9, 7, "k"], [10, 7, "k"],
] as const;

/** A small coin sprite for the credits/high-score list. */
export const COIN: readonly Pixel[] = [
  [1, 0, "y"], [2, 0, "y"],
  [0, 1, "y"], [1, 1, "w"], [2, 1, "y"], [3, 1, "y"],
  [0, 2, "y"], [1, 2, "y"], [2, 2, "w"], [3, 2, "y"],
  [1, 3, "y"], [2, 3, "y"],
] as const;

/** A heart sprite (extra-life marker). */
export const HEART: readonly Pixel[] = [
  [1, 0, "p"], [3, 0, "p"],
  [0, 1, "p"], [1, 1, "pl"], [2, 1, "p"], [3, 1, "pl"], [4, 1, "p"],
  [0, 2, "p"], [1, 2, "p"], [2, 2, "p"], [3, 2, "p"], [4, 2, "p"],
  [1, 3, "p"], [2, 3, "p"], [3, 3, "p"],
  [2, 4, "p"],
] as const;

/** A star sprite (hi-score burst). */
export const STAR: readonly Pixel[] = [
  [2, 0, "y"],
  [2, 1, "y"],
  [0, 2, "y"], [1, 2, "y"], [2, 2, "w"], [3, 2, "y"], [4, 2, "y"],
  [1, 3, "y"], [2, 3, "y"], [3, 3, "y"],
  [1, 4, "y"], [3, 4, "y"],
] as const;

/* ----------------------------- helpers --------------------------------- */

function row(
  x0: number,
  x1: number,
  y: number,
  c: keyof typeof SPRITE_PALETTE,
): Pixel[] {
  const out: Pixel[] = [];
  for (let x = x0; x <= x1; x++) out.push([x, y, c] as Pixel);
  return out;
}

function border(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  c: keyof typeof SPRITE_PALETTE,
): Pixel[] {
  const out: Pixel[] = [];
  for (let x = x0; x <= x1; x++) {
    out.push([x, y0, c] as Pixel);
    out.push([x, y1, c] as Pixel);
  }
  for (let y = y0 + 1; y < y1; y++) {
    out.push([x0, y, c] as Pixel);
    out.push([x1, y, c] as Pixel);
  }
  return out;
}

/**
 * Render a sprite's pixels into a CSS `box-shadow` value. Each pixel becomes
 * one shadow tuple `${x}px ${y}px 0 0 ${color}` on a 1px×1px anchor.
 * `scale` multiplies the pixel pitch so the same sprite can render at 2x/3x.
 */
export function spriteToBoxShadow(
  pixels: readonly Pixel[],
  scale = 1,
): string {
  return pixels
    .map(([x, y, c]) => `${x * scale}px ${y * scale}px 0 0 ${SPRITE_PALETTE[c]}`)
    .join(", ");
}

/** Sprite bounding-box width/height in pixel units (for sizing the anchor). */
export function spriteSize(pixels: readonly Pixel[]): {
  width: number;
  height: number;
} {
  let maxX = 0;
  let maxY = 0;
  for (const [x, y] of pixels) {
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  return { width: maxX + 1, height: maxY + 1 };
}

// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/gugi";
import "@fontsource/press-start-2p";
import "@fontsource/vt323";

export const gugi = { variable: "" };
export const pressStart2P = { variable: "" };
export const vt323 = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes re-render immediately. When it is
 * true the arcade holds still: the sprite parks on frame 0, the CRT
 * aberration ghosts never appear, the scanline grille is a static layer,
 * and the marquee reads as a single line. Keyboard and touch input are
 * never disabled — only autonomous motion is.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

/** Scroll speed (px/ms) that counts as a full-tilt run down the cabinet bank. */
const V_MAX = 2.4;
/** Energy attack / release per 60fps-normalized frame — the CRT notices a
 *  rush fast and takes its time settling back, like phosphor afterglow. */
const ATTACK = 0.16;
const RELEASE = 0.05;
/** Aberration envelope: max RGB-split offset (px) and ghost opacity. */
const MAX_SHIFT_PX = 3;
const MAX_GHOST = 0.9;
/** Below this energy, after this much scroll silence, the loop parks. */
const SLEEP_AT = 0.004;
const SLEEP_AFTER_MS = 320;

/**
 * Turns page scroll VELOCITY (not position) into a smoothed 0→1 "rush"
 * energy and writes it to two CSS custom properties on the entry root:
 *
 *   --pixel-shift  (0–3px)   — how far the chromatic-aberration ghosts split
 *   --pixel-ghost  (0–0.9)   — how visible those ghosts are
 *
 * At rest both are 0 and the display headings render with only the idle
 * CRT breathe (a separate, slower, always-on animation). Scroll hard and
 * the headings smear cyan-left / magenta-right like a knocked CRT; stop,
 * and everything eases back to crisp over the release curve.
 *
 * The returned ref carries the same 0→1 number for any JS consumer that
 * wants it (the marquee speeds up with the same energy). The loop only
 * runs while there is something to decay: it wakes on the first scroll
 * event and parks itself once energy has drained, so an idle page costs
 * zero frames. Under prefers-reduced-motion it writes the resting values
 * once and never listens at all.
 */
export function useScrollRush(
  rootRef: RefObject<HTMLElement | null>,
  reduced: boolean,
): RefObject<number> {
  const energyRef = useRef(0);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const write = (value: number) => {
      energyRef.current = value;
      root.style.setProperty(
        "--pixel-shift",
        `${(value * MAX_SHIFT_PX).toFixed(2)}px`,
      );
      root.style.setProperty("--pixel-ghost", (value * MAX_GHOST).toFixed(3));
    };

    if (reduced) {
      write(0);
      return;
    }

    let raf = 0;
    let running = false;
    let lastY = 0;
    let lastT = 0;
    let lastScrollAt = 0;
    let energy = 0;

    const park = () => {
      running = false;
      cancelAnimationFrame(raf);
      energy = 0;
      write(0);
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(Math.max(now - lastT, 1), 64);
      lastT = now;

      const y = window.scrollY;
      const v = Math.abs(y - lastY) / dt; // px per ms
      lastY = y;
      if (v > 0.01) lastScrollAt = now;

      const target = Math.min(1, v / V_MAX);
      const k = (target > energy ? ATTACK : RELEASE) * (dt / 16.7);
      energy += (target - energy) * Math.min(1, k);
      write(energy);

      if (energy < SLEEP_AT && now - lastScrollAt > SLEEP_AFTER_MS) park();
    };

    const wake = () => {
      if (running || document.hidden) return;
      running = true;
      lastY = window.scrollY;
      lastT = performance.now();
      lastScrollAt = lastT;
      raf = requestAnimationFrame(step);
    };

    const onVisibility = () => {
      if (document.hidden && running) park();
    };

    window.addEventListener("scroll", wake, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      window.removeEventListener("scroll", wake);
      document.removeEventListener("visibilitychange", onVisibility);
      cancelAnimationFrame(raf);
      write(0);
    };
  }, [rootRef, reduced]);

  return energyRef;
}

"use client";

import { useEffect, useState, type RefObject } from "react";

/** Frame interval in ms — a calm arcade idle, not a flicker. */
const FRAME_MS = 420;

/**
 * Cycles a pixel sprite between N animation frames by returning a frame
 * index the component uses to pick its box-shadow grid. The cycle is
 * rAF-gated and pauses (a) when the sprite leaves the viewport via
 * IntersectionObserver and (b) when the tab is hidden — so an offscreen
 * mascot costs zero frames. Under prefers-reduced-motion the hook parks
 * on frame 0 and never starts a loop, which is exactly the static,
 * composed sprite the rubric asks for.
 *
 * The component owns the sprite grids (they are data, not motion), so
 * pausing always leaves a complete, readable frame on screen — never a
 * blank or a half-drawn glyph.
 */
export function useSpriteCycle(
  targetRef: RefObject<HTMLElement | null>,
  frameCount: number,
  reduced: boolean,
): number {
  const [frame, setFrame] = useState(0);

  useEffect(() => {
    if (reduced || frameCount <= 1) return;
    const el = targetRef.current;
    if (!el) return;

    let raf = 0;
    let running = false;
    let visible = true;
    let last = 0;
    let acc = 0;
    let i = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 64);
      last = now;
      acc += dt;
      if (acc >= FRAME_MS) {
        acc = 0;
        i = (i + 1) % frameCount;
        setFrame(i);
      }
    };

    const sync = () => {
      const should = visible && !document.hidden;
      if (should && !running) {
        running = true;
        last = performance.now();
        raf = requestAnimationFrame(step);
      } else if (!should && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const onVisibility = () => sync();

    const io = new IntersectionObserver((hits) => {
      visible = hits[hits.length - 1].isIntersecting;
      sync();
    });
    io.observe(el);

    document.addEventListener("visibilitychange", onVisibility);
    sync();

    return () => {
      running = false;
      cancelAnimationFrame(raf);
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [targetRef, frameCount, reduced]);

  return frame;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { gugi, pressStart2P, vt323 } from "./fonts";
import Hero from "./components/Hero";
import HighScoreMarquee from "./components/HighScoreMarquee";
import GameGrid from "./components/GameGrid";
import PixelFooter from "./components/PixelFooter";
import CRTOverlay from "./components/CRTOverlay";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useScrollRush } from "./hooks/useScrollRush";

/**
 * PIXEL — an 8-bit arcade studio landing page.
 * A retro indie-game studio for games that fit in 32 kilobytes. The page is
 * a 2003 arcade that still believes someone is playing: a hero mascot drawn
 * one CSS box-shadow per pixel, a CRT scanline + chromatic-aberration glow
 * that breathes on idle and smears when you scroll, and a chiptune
 * high-score marquee. Saturated dopamine color — bubblegum, cyan, chrome,
 * acid — and the warm optimism of a CRT, not vaporwave's melancholic mauve.
 *
 * `.pixel-js` is added on mount so every enhancement (CRT flicker, sprite
 * cycle, scroll-rush aberration, marquee motion) is JS-gated — with
 * JavaScript disabled the full page reads top to bottom: static sprites,
 * a static scanline grille, static scores.
 */
export default function PixelPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const energyRef = useScrollRush(rootRef, reduced);

  useEffect(() => {
    // Imperative on purpose: the class is a signal to CSS that JS is alive,
    // not React state — and it never changes once set.
    rootRef.current?.classList.add("pixel-js");
    window.parent?.postMessage(
      { type: "oneshot:ready", slug: "pixel" },
      "*",
    );
  }, []);

  return (
    <div
      id="pixel-top"
      ref={rootRef}
      className={`${pressStart2P.variable} ${gugi.variable} ${vt323.variable} pixel-root`}
    >
      <CRTOverlay reduced={reduced} />
      <Hero reduced={reduced} />
      <HighScoreMarquee reduced={reduced} energyRef={energyRef} />
      <main>
        <GameGrid />
      </main>
      <PixelFooter />
    </div>
  );
}

/* ==========================================================================
   PIXEL — 8-bit arcade studio
   retro-y2k · dopamine color on CRT black · cheerful, saturated, optimistic
   Scoped by convention to .pixel-root; classes prefixed pixel-.
   ========================================================================== */

.pixel-root {
  /* -- palette (contrast measured against ground #0a0a12) --------------- */
  --pixel-ground: #0a0a12;     /* page background — the CRT ground */
  --pixel-void: #050509;       /* deeper than ground — footer, marquee, stage */
  --pixel-panel: #14141f;      /* card / cabinet bodies (body 11.7:1 on it) */
  --pixel-bubblegum: #ff3d8a;  /* THE accent — title, INSERT COIN, marquee marks (5.9:1) */
  --pixel-cyan: #00e5ff;       /* links, focus, hi-score digits (12.8:1, AAA) */
  --pixel-acid: #fff44f;       /* acid yellow — lamps, score highlights (17.2:1, AAA) */
  --pixel-mint: #4dff9f;       /* mint — CONTINUE, secondary accent (15.1:1, AAA) */
  --pixel-violet: #b967ff;     /* magenta-violet — small labels, chrome (6.0:1, AA) */
  --pixel-chrome: #c8d0d8;     /* reading text — long copy allowed here (12.7:1, AAA) */
  --pixel-haze: #8a93a8;       /* secondary text, captions, Korean glosses (6.6:1, AA) */
  --pixel-line: rgba(185, 103, 255, 0.28); /* hairlines — decorative */

  /* -- aberration envelope (written live by useScrollRush) -------------- */
  --pixel-shift: 0px;
  --pixel-ghost: 0;

  /* -- type --------------------------------------------------------------- */
  --pixel-font-display: var(--font-pixel-display), var(--font-pixel-ko), monospace;
  --pixel-font-ko: var(--font-pixel-ko), sans-serif;
  --pixel-font-mono: var(--font-pixel-mono), var(--font-pixel-ko), monospace;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--pixel-ground);
  color: var(--pixel-chrome);
  font-family: var(--pixel-font-mono);
  font-size: clamp(15px, 1vw + 11px, 18px);
  line-height: 1.55;
  overflow-x: hidden;
  overflow-x: clip;
  -webkit-font-smoothing: none;
  font-smooth: never;
}

/* Hangul is first-class: it always renders in Gugi (never fallback sans),
   with mono tracking turned off and words kept whole. */
.pixel-root :lang(ko) {
  font-family: var(--pixel-font-ko);
  letter-spacing: 0;
  word-break: keep-all;
}

/* The hidden attribute must win over any display we set. */
.pixel-root [hidden] {
  display: none !important;
}

/* Pixel selection — bubblegum block, ground text */
.pixel-root ::selection {
  background: var(--pixel-bubblegum);
  color: var(--pixel-ground);
  text-shadow: none;
}

/* Keyboard focus: cyan ring with a bubblegum halo — arcade signage */
