/* ==========================================================================
   CRT overlay — full-page scanline grille + vignette (crt-scanline)
   Fixed over the viewport, pointer-events: none, behind text. The grille
   breathes via JS opacity (CRTOverlay.tsx); reduced motion renders it
   static. The vignette is a soft radial darkening at the screen edges —
   the curved-tube feel — and never touches text contrast (text sits
   inside the bright center).
   ========================================================================== */

.pixel-crt {
  position: fixed;
  inset: 0;
  z-index: 9000;
  pointer-events: none;
}

.pixel-crt__scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(5, 5, 9, 0.55) 0 1px,
    transparent 1px 3px
  );
  opacity: 0.16;
  mix-blend-mode: multiply;
}

.pixel-crt__vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      120% 120% at 50% 50%,
      transparent 58%,
      rgba(5, 5, 9, 0.55) 100%
    );
}

/* ==========================================================================
   Chromatic aberration — .pixel-ab (the smear)
   Two pseudo-element ghosts of the same text (cyan left, magenta right)
   ride --pixel-shift / --pixel-ghost on top of an always-on idle breathe.
   mix-blend-mode: screen means ghosts only ADD light over the base glyphs
   — the readable text never moves and never loses contrast. At rest the
   idle breathe gives ±1px; scroll rush (via useScrollRush) drives it to
   ±3px. Reduced motion removes the ghosts entirely.
   ========================================================================== */

.pixel-ab {
  position: relative;
}

.pixel-ab::before,
.pixel-ab::after {
  content: attr(data-text) / "";
  position: absolute;
  inset: 0;
  opacity: var(--pixel-ghost, 0);
  mix-blend-mode: screen;
  pointer-events: none;
  will-change: transform, opacity;
}

.pixel-ab::before {
  color: var(--pixel-cyan);
  transform: translate3d(calc(var(--pixel-shift, 0px) * -1), 0, 0);
}

.pixel-ab::after {
  color: var(--pixel-bubblegum);
  transform: translate3d(var(--pixel-shift, 0px), 0, 0);
}

/* The idle CRT breathe — always-on at rest, the screen is alive even when
   you are not scrolling. The ghosts sit at a low idle opacity so the base
   glyphs stay crisp; scroll rush raises the opacity via --pixel-ghost. */
.pixel-js .pixel-ab::before {
  animation: pixel-ab-idle-l 6s ease-in-out infinite;
}
.pixel-js .pixel-ab::after {
  animation: pixel-ab-idle-r 6s ease-in-out infinite;
}

