  color: var(--pixel-haze);
}

.pixel-footer__copy {
  margin: 0;
  color: var(--pixel-haze);
  font-size: 0.86rem;
}

.pixel-footer__copy [lang="ko"] {
  display: block;
  margin-top: 0.25rem;
}

/* ==========================================================================
   Pixel sprite primitive — the box-shadow renderer (ascii-render)
   A 1px×1px anchor carries the whole sprite as a box-shadow list. The
   wrapper sizes to the sprite's bounding box; the anchor is positioned at
   the top-left so every shadow tuple (x, y, 0, color) lands in grid.
   ========================================================================== */

.pixel-sprite {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  image-rendering: pixelated;
}

.pixel-sprite__anchor {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
  pointer-events: none;
}

.pixel-char {
  position: relative;
  display: inline-block;
}

.pixel-char__blink {
  position: absolute;
  top: 0;
  left: 0;
}

.pixel-char__blink .pixel-sprite {
  position: absolute;
  top: 0;
  left: 0;
}

/* ==========================================================================
   Keyframes — transform / opacity only
   ========================================================================== */

@keyframes pixel-lamp {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* Idle CRT breathe — cyan ghost drifts left, magenta ghost drifts right,
   both at a low idle opacity. Scroll rush then layers the --pixel-shift /
   --pixel-ghost envelope on top via the custom properties. */
@keyframes pixel-ab-idle-l {
  0%,
  100% {
    transform: translate3d(-1px, 0, 0);
    opacity: 0.18;
  }
  50% {
    transform: translate3d(1px, 0, 0);
    opacity: 0.34;
  }
}

@keyframes pixel-ab-idle-r {
  0%,
  100% {
    transform: translate3d(1px, 0, 0);
    opacity: 0.18;
  }
  50% {
    transform: translate3d(-1px, 0, 0);
    opacity: 0.34;
  }
}

/* ==========================================================================
   Reduced motion — one beautiful still of the arcade.
   (The JS side checks the same media query: the sprite cycle parks on
   frame 0, the scroll-rush loop never starts, the CRT flicker never
   starts, the marquee never moves. The static scanline grille stays —
   it is a real layer, not motion.)
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .pixel-root {
    --pixel-shift: 0px;
    --pixel-ghost: 0;
  }

  .pixel-ab::before,
  .pixel-ab::after {
    content: none;
  }

  .pixel-js .pixel-ab::before,
  .pixel-js .pixel-ab::after,
  .pixel-js .pixel-hero__lamp {
    animation: none;
  }

  /* The grille holds at a steady, composed opacity — still a CRT, no flicker */
  .pixel-crt__scan {
    opacity: 0.18;
  }
}
